import { useAuth } from "@/_core/hooks/useAuth";
import { BrandMark } from "@/components/BrandMark";
import { CatalogOriginLabel } from "@/components/CatalogOriginLabel";
import { Button } from "@/components/ui/button";
import { trpc } from "@/lib/trpc";
import { NotificationBell } from "@/components/NotificationBell";
import { STAFF_ORDERS_REFRESH_MS } from "@/lib/order-alarm";
import { NEXT_ACTION_LABEL, ORDER_STATUS_LABEL, canMarkItemsOutOfStock, canRoleAdvanceOrder, canStaffCancel, isOrderClosed, nextOrderStatus, type OrderStatus } from "@shared/order-flow";
import { OWNER_DISPLAY_NAME } from "@/lib/brand";
import { buildCatalogProductPayload, buildCatalogProductUpdatePayload, type CatalogProductDraft, type CatalogProductPayload, type CatalogProductUpdatePayload } from "@/../../shared/catalog";
import { DEFAULT_SPLASH_DURATION_MS, MAX_SPLASH_DURATION_MS, MIN_SPLASH_DURATION_MS, SPLASH_DURATION_SETTING_KEY, formatSplashDurationLabel, parseSplashDuration } from "@/../../shared/splash-settings";
import { calculateDiscountPercent, calculateSalePrice, formatDiscountBadge, formatPriceInput } from "@/../../shared/catalog-pricing";
import { BarChart3, Bell, Boxes, CalendarDays, Camera, ChevronDown, ChevronRight, ClipboardCheck, ClipboardList, CreditCard, Eye, EyeOff, Gauge, ImagePlus, Leaf, LockKeyhole, MapPin, PackageCheck, Pencil, Phone, Plus, Power, Send, Store, Trash2, Truck, UserPlus, UserX, Users, X } from "lucide-react";
import { ChangeEvent, FormEvent, useEffect, useState } from "react";
import { toast } from "sonner";
import { Link, useLocation } from "wouter";

type PortalKind = "shop_owner" | "delivery_boy" | "admin";
type OrderItemRow = { id: number; title: string; variantTitle: string | null; quantity: number; lineTotal: string; itemStatus: "ok" | "out_of_stock" };
type Order = { id: number; orderNumber: string; apartmentUnit: string; total: string; status: OrderStatus; paymentMethod: "online_checkout" | "upi_qr" | "cash_on_delivery" | "pay_after_delivery"; paymentStatus: "pending" | "paid" | "failed" | "refunded"; cancelReason?: string | null; items?: OrderItemRow[] };
type InventoryProduct = { id: number; name: string; description: string | null; imageUrl: string | null; countryOfOrigin: string; price: string; compareAtPrice: string | null; stockQuantity: number; unitLabel: string; isAvailable: boolean };
type Shop = { id: number; name: string };
type ExchangeRow = { request: { id: number; orderId: number; reason: string; status: "requested" | "approved" | "rejected" | "completed"; createdAt: Date }; order: { orderNumber: string; apartmentUnit: string } };
type ServiceKind = "electrician" | "plumber" | "tuition" | "fitness" | "car" | "bike";
type ServiceRequestStatus = "submitted" | "contacted" | "closed";
type ServiceHistoryRow = { id: number; residentUserId: number; serviceKind: ServiceKind; phone: string; blockNumber: string; flatNumber: string; selectedServices: string[]; issueDescription: string; status: ServiceRequestStatus; createdAt: Date | string; updatedAt: Date | string; name: string; building: string };
type ProductPayload = CatalogProductPayload;
type RoadmapGateKey = "residentValidation" | "supplierSetup" | "complianceReview" | "qaStatus" | "pilotStatus" | "expansionStatus";
type RoadmapStatus = "pending" | "in_progress" | "complete" | "blocked";
type RoadmapReadiness = { metrics: { verifiedResidents: number; activeShops: number; availableProducts: number; deliveryPartners: number; totalOrders: number; openOrders: number; deliveredOrders: number; averageOrderValue: number; stockOuts: number; serviceRequests: number; openServiceRequests: number }; gates: Record<RoadmapGateKey, RoadmapStatus>; settings: { pilotApartments: string; notes: string } };
const roadmapGateLabels: Record<RoadmapGateKey, string> = { residentValidation: "Resident survey / validation", supplierSetup: "Local suppliers + fulfilment", complianceReview: "Society permission + compliance", qaStatus: "Internal QA", pilotStatus: "Two-apartment pilot", expansionStatus: "Expansion gate" };
const roadmapStatusLabels: Record<RoadmapStatus, string> = { pending: "Pending", in_progress: "In progress", complete: "Complete", blocked: "Blocked" };

const serviceKindLabels: Record<ServiceKind, string> = { electrician: "Electrician", plumber: "Plumber", tuition: "Home Tuition", fitness: "Fitness Provider", car: "Car Service", bike: "Bike Service" };
const serviceStatusStyles: Record<ServiceRequestStatus, string> = { submitted: "bg-amber-100 text-amber-800", contacted: "bg-blue-100 text-blue-800", closed: "bg-emerald-100 text-emerald-800" };
const formatServiceDate = (value: Date | string) => new Date(value).toLocaleString([], { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });

export function buildProductCreatorSubmitPayload(draft: CatalogProductDraft, isAdmin: boolean): CatalogProductPayload | null {
  if (!draft.name.trim() || !draft.price || (isAdmin && !draft.shopId)) return null;
  return buildCatalogProductPayload(draft);
}

export function buildInventoryCardSubmitPayload(id: number, draft: CatalogProductDraft): CatalogProductUpdatePayload {
  return buildCatalogProductUpdatePayload(id, draft);
}

const portalCopy: Record<PortalKind, { label: string; title: string; intro: string }> = {
  shop_owner: { label: "Shop owner", title: "Your shop, at a glance.", intro: "Receive fresh orders, confirm preparation, and keep your HariCart inventory ready." },
  delivery_boy: { label: "Delivery partner", title: "The short route home.", intro: "See only your assigned orders and keep every verified-apartment hand-off clear and timely." },
  admin: { label: "Admin control", title: "One community, full control.", intro: "Govern residents, catalog, operations, communications, and the HariCart brand from one workspace." },
};


export default function OperationsPortal() {
  const [location] = useLocation();
  const kind: PortalKind = location.startsWith("/delivery") ? "delivery_boy" : location.startsWith("/admin") ? "admin" : "shop_owner";
  const { user, isAuthenticated } = useAuth();
  const allowed = user?.role === kind || user?.role === "admin";
  const enabled = Boolean(isAuthenticated && allowed);
  const utils = trpc.useUtils();
  const orders = trpc.community.orders.mine.useQuery(undefined, { enabled, refetchInterval: STAFF_ORDERS_REFRESH_MS });
  const notifications = trpc.community.notifications.list.useQuery(undefined, { enabled, refetchInterval: 15_000 });
  const exchanges = trpc.community.exchanges.mine.useQuery(undefined, { enabled });
  const shopInventory = trpc.community.shop.inventory.list.useQuery(undefined, { enabled: enabled && kind === "shop_owner" });
  const serviceRequests = trpc.community.resident.ownerServiceRequests.useQuery(undefined, { enabled: enabled && (kind === "shop_owner" || kind === "admin") });
  const adminProducts = trpc.admin.catalog.products.useQuery(undefined, { enabled: enabled && kind === "admin" });
  const adminShops = trpc.admin.operations.shops.useQuery(undefined, { enabled: enabled && kind === "admin" });
  const advance = trpc.community.orders.advance.useMutation({ onSuccess: () => { orders.refetch(); notifications.refetch(); }, onError: error => toast.error(error.message) });
  const cancelOrder = trpc.community.orders.cancel.useMutation({ onSuccess: data => { orders.refetch(); notifications.refetch(); toast.success(data.refundDue ? `Order cancelled. Refund ₹${Number(data.refundDue).toFixed(2)} to the customer.` : "Order cancelled. Stock is back on the shelf."); }, onError: error => toast.error(error.message) });
  const markOutOfStock = trpc.community.orders.markItemOutOfStock.useMutation({ onSuccess: data => { orders.refetch(); notifications.refetch(); void utils.commerce.products.list.invalidate(); toast.success(data.cancelled ? "Nothing left in this order, so it was cancelled." : `Item removed. New total ₹${Number(data.total).toFixed(2)}. The customer has been told.`); }, onError: error => toast.error(error.message) });
  const recordPayment = trpc.community.orders.recordPayment.useMutation({ onSuccess: () => { orders.refetch(); notifications.refetch(); toast.success("Payment marked as collected"); }, onError: error => toast.error(error.message) });
  const dashboard = trpc.admin.dashboard.useQuery(undefined, { enabled: enabled && kind === "admin", refetchInterval: 15_000 });
  const users = trpc.admin.users.list.useQuery(undefined, { enabled: enabled && kind === "admin" });
  const [announcement, setAnnouncement] = useState("");
  const [selectedOrderId, setSelectedOrderId] = useState<number | null>(null);
  const selectedOrder = trpc.admin.operations.orderDetails.useQuery({ orderId: selectedOrderId || 1 }, { enabled: enabled && kind === "admin" && Boolean(selectedOrderId) });
  const broadcast = trpc.admin.notifications.broadcast.useMutation({ onSuccess: () => { setAnnouncement(""); notifications.refetch(); } });
  const createProduct = trpc.community.shop.inventory.create.useMutation({ onSuccess: async () => { await Promise.all([shopInventory.refetch(), adminProducts.refetch(), utils.commerce.products.list.invalidate()]); toast.success("Catalog item added and published to HariCart"); }, onError: error => toast.error(error.message) });
  const reviewExchange = trpc.community.exchanges.review.useMutation({ onSuccess: () => { exchanges.refetch(); notifications.refetch(); } });
  const updateServiceRequest = trpc.community.resident.updateServiceRequestStatus.useMutation({ onSuccess: () => { serviceRequests.refetch(); toast.success("Service request updated"); }, onError: error => toast.error(error.message) });
  const unread = (notifications.data || []).filter(item => !item.isRead).length;

  if (!isAuthenticated || !allowed) return <ProtectedWorkspace kind={kind} />;

  const products = (kind === "admin" ? adminProducts.data || [] : shopInventory.data || []) as InventoryProduct[];
  return <div className="min-h-screen bg-[#f7f4eb]">
    <header className="border-b bg-card"><div className="container flex h-20 items-center justify-between"><Link href="/"><BrandMark /></Link><div className="flex items-center gap-2"><NotificationBell /><Link href="/"><Button variant="outline" size="sm" className="rounded-full">Storefront</Button></Link></div></div></header>
    <main className="container py-10">
      <section className="mb-8 flex flex-col gap-4 border-b pb-7 md:flex-row md:items-end md:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.17em] text-primary">{portalCopy[kind].label}</p><h1 className="mt-2 font-editorial text-4xl font-semibold tracking-tight">{portalCopy[kind].title}</h1><p className="mt-3 max-w-xl leading-7 text-muted-foreground">{portalCopy[kind].intro}</p></div><div className="rounded-2xl bg-primary px-4 py-3 text-sm text-primary-foreground"><b>{kind === "admin" ? OWNER_DISPLAY_NAME : user?.name || "Signed in"}</b><span className="mx-2 opacity-60">·</span>{user?.role}</div></section>
      {(kind === "shop_owner" || kind === "admin") && <ServiceHistoryPanel rows={(serviceRequests.data || []) as ServiceHistoryRow[]} updating={updateServiceRequest.isPending} onUpdate={(requestId, status) => updateServiceRequest.mutate({ requestId, status })} />}
      {kind === "admin" && <RoadmapReadinessPanel />}
      {kind === "admin" && <AdminSnapshot dashboard={dashboard.data} people={users.data?.length || 0} announcement={announcement} setAnnouncement={setAnnouncement} onSend={() => broadcast.mutate({ title: "HariCart update", body: announcement, audience: "all" })} sending={broadcast.isPending} />}
      {kind === "admin" && <><AdminControlPanel /><AdminCommercePanel /><AdminInvitePanel /><AdminReportsPanel /><AdminAdvancedPanel /></>}
      {(kind === "shop_owner" || kind === "admin") && <section className="mt-6 grid gap-6 lg:grid-cols-2"><ProductCreator shops={(adminShops.data || []) as Shop[]} isAdmin={kind === "admin"} creating={createProduct.isPending} onCreate={payload => createProduct.mutateAsync(payload)} /><InventoryPanel products={products} isAdmin={kind === "admin"} /></section>}
      <section className="mt-7 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Metric icon={kind === "delivery_boy" ? Truck : ClipboardList} label={kind === "delivery_boy" ? "Assigned drop-offs" : "Orders to action"} value={String((orders.data || []).filter(order => order.status !== "delivered").length)} /><Metric icon={PackageCheck} label="Lifecycle" value="Live" /><Metric icon={Bell} label="Unread updates" value={String(unread)} /><Metric icon={kind === "admin" ? BarChart3 : Boxes} label={kind === "admin" ? "People managed" : "Inventory"} value={kind === "admin" ? String(users.data?.length || 0) : "Scoped"} /></section>
      <section className="mt-6 grid gap-6 lg:grid-cols-[1.15fr_.85fr]"><OrderQueue orders={(orders.data || []) as Order[]} role={user?.role === "admin" ? "admin" : kind} advancing={advance.isPending} collectingPayment={recordPayment.isPending} cancelling={cancelOrder.isPending} markingStock={markOutOfStock.isPending} showView={kind === "admin"} onView={setSelectedOrderId} onAdvance={(orderId, status) => advance.mutate({ orderId, status })} onCollectPayment={orderId => recordPayment.mutate({ orderId, status: "paid", providerReference: "collected-by-operations" })} onCancel={(orderId, reason) => cancelOrder.mutate({ orderId, reason })} onOutOfStock={(orderId, orderItemId, title) => { if (window.confirm(`Mark "${title}" as out of stock? It will be removed from this order and hidden from the shop.`)) markOutOfStock.mutate({ orderId, orderItemId }); }} /><NotificationPanel notifications={notifications.data || []} /></section>
      {kind === "admin" && selectedOrderId && <AdminOrderDetails details={selectedOrder.data} loading={selectedOrder.isLoading} onClose={() => setSelectedOrderId(null)} />}
      {(kind === "shop_owner" || kind === "admin") && <ExchangeReviewPanel rows={(exchanges.data || []) as ExchangeRow[]} reviewing={reviewExchange.isPending} onReview={(exchangeId, status) => reviewExchange.mutate({ exchangeId, status })} />}
    </main>
  </div>;
}

function ProtectedWorkspace({ kind }: { kind: PortalKind }) { return <div className="min-h-screen bg-[#f7f4eb]"><header className="border-b bg-card"><div className="container flex h-20 items-center justify-between"><Link href="/"><BrandMark /></Link><Link href="/"><Button variant="outline" size="sm" className="rounded-full">Storefront</Button></Link></div></header><main className="container grid min-h-[500px] place-items-center py-10"><div className="max-w-md rounded-[1.75rem] border border-dashed bg-card p-8 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-accent text-primary"><LockKeyhole className="h-6 w-6" /></span><h1 className="mt-5 font-editorial text-3xl font-semibold">This workspace is role protected.</h1><p className="mt-3 leading-7 text-muted-foreground">Only approved {portalCopy[kind].label.toLowerCase()} accounts can access this operational data.</p><Link href="/"><Button className="mt-6 rounded-full">Return to storefront</Button></Link></div></main></div>; }

function ProductCreator({ shops, isAdmin, creating, onCreate }: { shops: Shop[]; isAdmin: boolean; creating: boolean; onCreate: (payload: ProductPayload) => void }) {
  const [name, setName] = useState("");
  const [price, setPrice] = useState("");
  const [compareAtPrice, setCompareAtPrice] = useState("");
  const [discountPercent, setDiscountPercent] = useState("");
  const [countryOfOrigin, setCountryOfOrigin] = useState("India");
  const [stock, setStock] = useState("1");
  const [unit, setUnit] = useState("kg");
  const [imageUrl, setImageUrl] = useState("");
  const [description, setDescription] = useState("");
  const [shopId, setShopId] = useState("");
  const [isAvailable, setIsAvailable] = useState(true);
  const uploadImage = trpc.community.shop.inventory.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const handlePhoto = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 5 * 1024 * 1024) {
      toast.error("Choose a JPG, PNG, or WEBP photo up to 5 MB.");
      return;
    }
    const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("Unable to read photo")); reader.readAsDataURL(file); });
    try {
      const uploaded = await uploadImage.mutateAsync({ fileName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataBase64: dataUrl.split(",")[1] || "" });
      setImageUrl(uploaded.url);
      toast.success("Product photo uploaded");
    } catch (error) { toast.error(error instanceof Error ? error.message : "Photo upload failed"); }
  };
  const inputClass = "h-14 w-full rounded-2xl border border-white/20 bg-transparent px-5 text-base text-white outline-none transition placeholder:text-white/55 focus:border-emerald-400 focus:ring-2 focus:ring-emerald-400/20";
  const submit = (event: FormEvent) => {
    event.preventDefault();
    const payload = buildProductCreatorSubmitPayload({ name, price, compareAtPrice, countryOfOrigin, stockQuantity: stock, unitLabel: unit, imageUrl, description, shopId, isAvailable }, isAdmin);
    if (!payload) return;
    onCreate(payload);
    setName(""); setPrice(""); setCompareAtPrice(""); setDiscountPercent(""); setCountryOfOrigin("India"); setStock("1"); setUnit("kg"); setImageUrl(""); setDescription(""); setIsAvailable(true);
  };
  return <section className="overflow-hidden rounded-[1.75rem] border border-slate-800 bg-[#0b1014] text-white shadow-xl">
    <div className="flex items-center justify-between border-b border-white/10 px-5 py-5 sm:px-7"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-full bg-emerald-400/15 text-emerald-300"><Plus className="h-5 w-5" /></span><div><p className="text-[11px] font-bold uppercase tracking-[.18em] text-emerald-300">Local Catalog</p><h2 className="mt-1 text-2xl font-semibold tracking-tight">Add item</h2></div></div><span className="text-sm font-semibold text-slate-300">Save</span></div>
    <form className="space-y-4 p-4 sm:p-7" onSubmit={submit}>
      <label className="group relative grid min-h-52 cursor-pointer place-items-center overflow-hidden rounded-2xl border border-slate-700 bg-[#1b2a33] text-center transition hover:border-emerald-400 sm:min-h-64">{imageUrl ? <><img src={imageUrl} alt="Selected product" className="absolute inset-0 h-full w-full object-cover opacity-90" /><span className="absolute inset-0 bg-slate-950/35" /><span className="relative rounded-full bg-slate-950/65 px-4 py-2 text-sm font-semibold">Change photo</span></> : <span className="relative grid justify-items-center gap-3 text-slate-200"><Camera className="h-10 w-10" /><span className="text-lg font-semibold">Add photos and videos</span><span className="text-xs text-slate-400">JPG, PNG or WEBP · up to 5 MB</span></span>}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={handlePhoto} className="sr-only" /></label>
      {uploadImage.isPending && <p className="text-center text-xs text-emerald-300">Uploading photo…</p>}
      {isAdmin && <select required value={shopId} onChange={event => setShopId(event.target.value)} aria-label="Choose a shop" className={inputClass}><option value="" className="bg-[#0b1014]">Choose a shop</option>{shops.map(shop => <option key={shop.id} value={shop.id} className="bg-[#0b1014]">{shop.name}</option>)}</select>}
      <div className="relative"><input required value={name} onChange={event => setName(event.target.value)} placeholder="Item name (required)" maxLength={160} className={inputClass} /><span className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-xs text-slate-500">{name.length}/160</span></div>
      <div className="grid gap-3 sm:grid-cols-2"><input required inputMode="decimal" value={compareAtPrice} onChange={event => { const next = formatPriceInput(event.target.value); setCompareAtPrice(next); if (next) setPrice(calculateSalePrice(next, discountPercent || "0")); }} placeholder="MRP (required) · ₹" aria-label="MRP" className={inputClass} /><input inputMode="decimal" min="0" max="100" value={discountPercent} onChange={event => { const next = formatPriceInput(event.target.value); setDiscountPercent(next); setPrice(calculateSalePrice(compareAtPrice, next)); }} placeholder="Discount % (optional)" aria-label="Discount percentage" className={inputClass} /></div>
      <input readOnly value={price} placeholder="Sale Price (calculated) · ₹" aria-label="Calculated sale price" className={inputClass + " bg-white/5 text-emerald-200"} />
      <div className="relative"><textarea value={description} onChange={event => setDescription(event.target.value)} placeholder="Description (optional)" maxLength={2000} className={inputClass + " h-28 resize-none py-4"} /><span className="pointer-events-none absolute bottom-3 right-4 text-xs text-slate-500">{description.length}/2000</span></div>
      <label className="relative block"><span className="absolute -top-2.5 left-4 z-10 bg-[#0b1014] px-1 text-xs text-slate-400">Country of origin (required)</span><select required value={countryOfOrigin} onChange={event => setCountryOfOrigin(event.target.value)} aria-label="Country of origin" className={inputClass}><option value="India" className="bg-[#0b1014]">India</option><option value="Imported" className="bg-[#0b1014]">Imported</option></select><ChevronDown className="pointer-events-none absolute right-5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /></label>
      <details open className="rounded-2xl border border-white/10 bg-white/[.03] p-4"><summary className="flex cursor-pointer list-none items-center justify-between text-base font-semibold text-emerald-300">More fields<ChevronDown className="h-4 w-4 text-slate-400" /></summary><div className="mt-4 grid gap-3 sm:grid-cols-2"><input type="number" min="0" value={stock} onChange={event => setStock(event.target.value)} placeholder="Stock quantity" aria-label="Stock quantity" className={inputClass} /><input value={unit} onChange={event => setUnit(event.target.value)} placeholder="Unit, e.g. kg or 500 g" aria-label="Unit" className={inputClass} /></div><p className="mt-3 text-xs leading-5 text-slate-400">Use stock 1 or more to show this item on the customer storefront with its photo.</p></details>
      <label className="flex cursor-pointer items-center justify-between gap-4 border-t border-white/10 pt-5"><span><span className="block text-base font-semibold">Hide this item</span><span className="mt-1 block text-xs leading-5 text-slate-400">When hidden, residents will not see it in the catalog.</span></span><span className={"relative h-8 w-14 rounded-full border transition " + (isAvailable ? "border-emerald-400/50 bg-emerald-500/25" : "border-slate-600 bg-slate-800")}><input type="checkbox" checked={!isAvailable} onChange={event => setIsAvailable(!event.target.checked)} aria-label="Hide this item" className="peer sr-only" /><span className={"absolute top-1 h-6 w-6 rounded-full bg-white shadow transition " + (isAvailable ? "left-7" : "left-1")}><EyeOff className={"mx-auto mt-1 h-4 w-4 " + (isAvailable ? "text-slate-400" : "text-slate-700")} /></span></span></label>
      <div className="flex flex-col gap-3 pt-2 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs leading-5 text-slate-400">Save publishes the item when it is available and in stock.</p><Button type="submit" disabled={creating || uploadImage.isPending} className="h-12 rounded-full bg-emerald-500 px-6 text-sm font-bold text-slate-950 hover:bg-emerald-400">{creating ? "Saving…" : "Save item"}<Plus className="ml-2 h-4 w-4" /></Button></div>
    </form>
  </section>;
}
function InventoryPanel({ products, isAdmin }: { products: InventoryProduct[]; isAdmin: boolean }) { return <section className="rounded-[1.5rem] border bg-card p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div className="flex items-center gap-2"><Boxes className="h-4 w-4 text-primary" /><div><p className="text-xs font-bold uppercase tracking-[.14em] text-primary">{isAdmin ? "Managed catalog" : "My catalog"}</p><h2 className="mt-1 font-editorial text-2xl font-semibold">WhatsApp-style product cards</h2></div></div><p className="max-w-sm text-sm leading-6 text-muted-foreground">Edit any item, update its photo or price, pause it for residents, or remove it from your catalog.</p></div><div className="mt-5 grid gap-4 sm:grid-cols-2">{products.map(product => <InventoryCard key={product.id} product={product} />)}{!products.length && <p className="rounded-xl border border-dashed p-5 text-sm text-muted-foreground sm:col-span-2">No products are available in this scope yet. Add your first vegetable above.</p>}</div></section>; }
function InventoryCard({ product }: { product: InventoryProduct }) {
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(product.name);
  const [description, setDescription] = useState(product.description || "");
  const [price, setPrice] = useState(product.price);
  const [compareAtPrice, setCompareAtPrice] = useState(product.compareAtPrice || product.price);
  const [discountPercent, setDiscountPercent] = useState(String(calculateDiscountPercent(product.compareAtPrice || product.price, product.price)));
  const [countryOfOrigin, setCountryOfOrigin] = useState(product.countryOfOrigin || "India");
  const [stock, setStock] = useState(String(product.stockQuantity));
  const [unit, setUnit] = useState(product.unitLabel);
  const [imageUrl, setImageUrl] = useState(product.imageUrl || "");
  const [isAvailable, setIsAvailable] = useState(product.isAvailable);
  const storefrontStatus = !isAvailable ? { label: "Paused", className: "bg-amber-100 text-amber-800" } : Number(stock) > 0 ? { label: "Live", className: "bg-white/90 text-primary" } : { label: "Out of stock", className: "bg-orange-100 text-orange-800" };
  const utils = trpc.useUtils();
  const refresh = () => { utils.community.shop.inventory.list.invalidate(); utils.admin.catalog.products.invalidate(); utils.commerce.products.list.invalidate(); };
  const update = trpc.community.shop.inventory.update.useMutation({ onSuccess: () => { refresh(); setEditing(false); toast.success("Catalog item updated"); }, onError: error => toast.error(error.message) });
  const remove = trpc.community.shop.inventory.remove.useMutation({ onSuccess: () => { refresh(); toast.success("Catalog item removed"); }, onError: error => toast.error(error.message) });
  const uploadImage = trpc.community.shop.inventory.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const handlePhoto = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]; event.target.value = ""; if (!file) return;
    if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 5 * 1024 * 1024) { toast.error("Choose a JPG, PNG, or WEBP photo up to 5 MB."); return; }
    const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("Unable to read photo")); reader.readAsDataURL(file); });
    try { const uploaded = await uploadImage.mutateAsync({ fileName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataBase64: dataUrl.split(",")[1] || "" }); setImageUrl(uploaded.url); toast.success("New photo uploaded"); } catch (error) { toast.error(error instanceof Error ? error.message : "Photo upload failed"); }
  };
  const submit = () => update.mutate(buildInventoryCardSubmitPayload(product.id, { name, description, price, compareAtPrice, countryOfOrigin, stockQuantity: stock, unitLabel: unit, imageUrl, isAvailable }));
  const discountBadge = formatDiscountBadge(compareAtPrice, price);
  return <article className="overflow-hidden rounded-2xl border bg-card shadow-sm"><div className="relative aspect-[4/3] bg-[#ede7d8]">{imageUrl ? <img src={imageUrl} alt={name} className="h-full w-full object-cover" /> : <div className="grid h-full place-items-center text-primary/60"><Leaf className="h-12 w-12" /></div>}<span className={`absolute left-3 top-3 rounded-full px-2.5 py-1 text-[11px] font-semibold ${storefrontStatus.className}`}>{storefrontStatus.label}</span></div><div className="p-4"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><h3 className="truncate font-semibold">{name}</h3><p className="mt-1 text-xs text-muted-foreground">₹{price} · {unit} · {stock} in stock {discountBadge ? `· ${discountBadge}` : ""}</p><CatalogOriginLabel value={product.countryOfOrigin} /></div><Button size="sm" variant="outline" className="shrink-0 rounded-full" onClick={() => setEditing(value => !value)}><Pencil className="mr-1.5 h-3.5 w-3.5" />{editing ? "Close" : "Edit"}</Button></div>{description && !editing && <p className="mt-3 line-clamp-2 text-sm leading-5 text-muted-foreground">{description}</p>}{editing && <div className="mt-4 grid gap-2"><input value={name} onChange={event => setName(event.target.value)} aria-label={`Name for ${product.name}`} className="rounded-lg border bg-background px-3 py-2 text-sm" /><div className="grid grid-cols-2 gap-2"><input value={compareAtPrice} onChange={event => { const next = formatPriceInput(event.target.value); setCompareAtPrice(next); setPrice(calculateSalePrice(next, discountPercent || "0")); }} inputMode="decimal" aria-label={`MRP for ${product.name}`} placeholder="MRP · ₹" className="rounded-lg border bg-background px-3 py-2 text-sm" /><input value={discountPercent} onChange={event => { const next = formatPriceInput(event.target.value); setDiscountPercent(next); setPrice(calculateSalePrice(compareAtPrice, next)); }} inputMode="decimal" min="0" max="100" aria-label={`Discount percentage for ${product.name}`} placeholder="Discount %" className="rounded-lg border bg-background px-3 py-2 text-sm" /></div><input readOnly value={price} placeholder="Sale Price (calculated) · ₹" aria-label={`Calculated sale price for ${product.name}`} className="rounded-lg border bg-muted px-3 py-2 text-sm" /><div className="grid grid-cols-2 gap-2"><input value={stock} onChange={event => setStock(event.target.value)} type="number" min="0" aria-label={`Stock for ${product.name}`} className="rounded-lg border bg-background px-3 py-2 text-sm" /><span className="flex items-center rounded-lg bg-primary/5 px-3 py-2 text-xs font-semibold text-primary">{discountBadge || "No discount"}</span></div><select value={countryOfOrigin} onChange={event => setCountryOfOrigin(event.target.value)} aria-label={`Country of origin for ${product.name}`} className="rounded-lg border bg-background px-3 py-2 text-sm"><option value="India">India</option><option value="Imported">Imported</option></select><input value={unit} onChange={event => setUnit(event.target.value)} placeholder="Unit, e.g. kg" className="rounded-lg border bg-background px-3 py-2 text-sm" /><textarea value={description} onChange={event => setDescription(event.target.value)} placeholder="Description" className="min-h-16 rounded-lg border bg-background px-3 py-2 text-sm" /><div className="flex flex-wrap items-center gap-2"><label className="inline-flex cursor-pointer items-center gap-2 rounded-full bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground"><ImagePlus className="h-3.5 w-3.5" />{uploadImage.isPending ? "Uploading…" : "Change photo"}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={handlePhoto} className="sr-only" /></label><Button type="button" size="sm" variant={isAvailable ? "outline" : "default"} className="rounded-full" onClick={() => setIsAvailable(value => !value)}>{isAvailable ? "Pause item" : "Show item"}</Button></div><div className="flex flex-wrap gap-2"><Button type="button" size="sm" disabled={update.isPending || uploadImage.isPending || !name.trim() || !price} className="rounded-full" onClick={submit}>{update.isPending ? "Saving…" : "Save changes"}</Button><Button type="button" size="sm" variant="outline" disabled={remove.isPending} className="rounded-full text-red-700 hover:text-red-800" onClick={() => { if (window.confirm(`Remove ${name} from the catalog?`)) remove.mutate({ id: product.id }); }}><Trash2 className="mr-1.5 h-3.5 w-3.5" />Remove</Button></div></div>}</div></article>;
}

function ExchangeReviewPanel({ rows, reviewing, onReview }: { rows: ExchangeRow[]; reviewing: boolean; onReview: (id: number, status: "approved" | "rejected" | "completed") => void }) { return <section className="mt-6 rounded-[1.5rem] border bg-card p-6"><div className="flex items-center gap-2"><PackageCheck className="h-5 w-5 text-primary" /><div><p className="text-xs font-bold uppercase tracking-[.14em] text-primary">Customer care</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Exchange requests</h2></div></div><div className="mt-5 space-y-3">{rows.map(({ request, order }) => <div key={request.id} className="rounded-xl bg-muted/60 p-4"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-semibold">{order.orderNumber} <span className="text-sm font-normal text-muted-foreground">· Unit {order.apartmentUnit}</span></p><span className="rounded-full bg-primary/10 px-3 py-1 text-xs font-semibold capitalize text-primary">{request.status}</span></div><p className="mt-2 text-sm text-muted-foreground">{request.reason}</p>{request.status === "requested" && <div className="mt-3 flex gap-2"><Button size="sm" className="rounded-full" disabled={reviewing} onClick={() => onReview(request.id, "approved")}>Approve</Button><Button size="sm" variant="outline" className="rounded-full" disabled={reviewing} onClick={() => onReview(request.id, "rejected")}>Decline</Button></div>}{request.status === "approved" && <Button size="sm" className="mt-3 rounded-full" disabled={reviewing} onClick={() => onReview(request.id, "completed")}>Mark exchange complete</Button>}</div>)}{!rows.length && <p className="rounded-xl border border-dashed p-5 text-sm text-muted-foreground">No exchange requests require a decision.</p>}</div></section>; }

function ServiceHistoryPanel({ rows, updating, onUpdate }: { rows: ServiceHistoryRow[]; updating: boolean; onUpdate: (requestId: number, status: ServiceRequestStatus) => void }) {
  const [filter, setFilter] = useState<"all" | ServiceKind>("all");
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const selected = rows.find(row => row.id === selectedId) || null;
  const visibleRows = filter === "all" ? rows : rows.filter(row => row.serviceKind === filter);
  return <section className="mt-6 rounded-[1.5rem] border bg-card p-6 shadow-sm">
    <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-primary">Owner operations</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Service History</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">Every resident request is saved here with the customer, apartment, issue, selected service, and request date.</p></div><select value={filter} onChange={event => setFilter(event.target.value as "all" | ServiceKind)} aria-label="Filter service history" className="rounded-xl border bg-background px-3 py-2 text-sm"><option value="all">All services</option>{Object.entries(serviceKindLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div>
    <div className="mt-5 grid gap-3">{visibleRows.map(row => <button type="button" key={row.id} onClick={() => setSelectedId(row.id)} className="group rounded-2xl border bg-background p-4 text-left transition hover:border-primary/40 hover:shadow-md"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[11px] font-bold text-primary">{serviceKindLabels[row.serviceKind]}</span><span className={`rounded-full px-2.5 py-1 text-[11px] font-semibold capitalize ${serviceStatusStyles[row.status]}`}>{row.status}</span></div><p className="mt-3 truncate font-semibold">{row.name} · Block {row.blockNumber}, Flat {row.flatNumber}</p><p className="mt-1 flex items-center gap-1.5 text-xs text-muted-foreground"><Phone className="h-3.5 w-3.5" />{row.phone}<span className="mx-1">·</span><CalendarDays className="h-3.5 w-3.5" />{formatServiceDate(row.createdAt)}</p></div><ChevronRight className="mt-1 h-5 w-5 shrink-0 text-muted-foreground transition group-hover:translate-x-0.5 group-hover:text-primary" /></div><p className="mt-3 line-clamp-2 text-sm text-muted-foreground">{row.issueDescription}</p></button>)}{!visibleRows.length && <p className="rounded-2xl border border-dashed p-6 text-center text-sm text-muted-foreground">No service requests found for this filter.</p>}</div>
    {selected && <div className="fixed inset-0 z-[90] grid place-items-center bg-[#071c10]/70 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-labelledby="service-history-title"><section className="max-h-[90vh] w-full max-w-xl overflow-y-auto rounded-[1.75rem] bg-card p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-primary">Service request #{selected.id}</p><h3 id="service-history-title" className="mt-1 font-editorial text-3xl font-semibold">{serviceKindLabels[selected.serviceKind]}</h3></div><button type="button" onClick={() => setSelectedId(null)} aria-label="Close service details" className="rounded-full p-2 text-muted-foreground hover:bg-muted hover:text-foreground"><X className="h-5 w-5" /></button></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-muted/60 p-3"><p className="text-[10px] font-bold uppercase tracking-wide text-muted-foreground">Customer</p><p className="mt-1 font-semibold">{selected.name}</p><p className="mt-1 flex items-center gap-1.5 text-sm text-primary"><Phone className="h-3.5 w-3.5" />{selected.phone}</p></div><div className="rounded-xl bg-muted/60 p-3"><p className="text-[10px] font-bold uppercase tracking-wide text-muted-foreground">Address</p><p className="mt-1 flex items-center gap-1.5 font-semibold"><MapPin className="h-3.5 w-3.5 text-primary" />Block {selected.blockNumber}, Flat {selected.flatNumber}</p><p className="mt-1 text-xs text-muted-foreground">{selected.building}</p></div></div><div className="mt-3 rounded-xl bg-muted/60 p-4"><p className="text-[10px] font-bold uppercase tracking-wide text-muted-foreground">Selected services</p><div className="mt-2 flex flex-wrap gap-2">{selected.selectedServices.length ? selected.selectedServices.map(service => <span key={service} className="rounded-full bg-background px-2.5 py-1 text-xs font-medium">{service}</span>) : <span className="text-sm text-muted-foreground">No specific option selected</span>}</div></div><div className="mt-3 rounded-xl border p-4"><p className="text-[10px] font-bold uppercase tracking-wide text-muted-foreground">Previous issue / customer note</p><p className="mt-2 whitespace-pre-wrap text-sm leading-6">{selected.issueDescription}</p></div><p className="mt-3 text-xs text-muted-foreground">Submitted {formatServiceDate(selected.createdAt)} · Last updated {formatServiceDate(selected.updatedAt)}</p><div className="mt-5 flex flex-wrap gap-2"><a href={`tel:${selected.phone}`}><Button type="button" className="rounded-full"><Phone className="mr-2 h-4 w-4" />Call customer</Button></a>{selected.status === "submitted" && <Button type="button" variant="outline" className="rounded-full" disabled={updating} onClick={() => onUpdate(selected.id, "contacted")}>Mark contacted</Button>}{selected.status === "contacted" && <Button type="button" variant="outline" className="rounded-full" disabled={updating} onClick={() => onUpdate(selected.id, "closed")}>Close request</Button>}{selected.status === "closed" && <span className="inline-flex items-center rounded-full bg-emerald-100 px-3 py-2 text-xs font-semibold text-emerald-800">Service closed</span>}</div></section></div>}
  </section>;
}

function RoadmapReadinessPanel() {
  const readiness = trpc.admin.roadmap.readiness.useQuery();
  const [draft, setDraft] = useState<RoadmapReadiness | null>(null);
  const save = trpc.admin.roadmap.saveSetting.useMutation({ onSuccess: () => { readiness.refetch(); toast.success("Roadmap readiness saved"); }, onError: error => toast.error(error.message) });
  useEffect(() => { if (readiness.data) setDraft(readiness.data as RoadmapReadiness); }, [readiness.data]);
  const current = draft || readiness.data as RoadmapReadiness | undefined;
  if (!current) return <section className="mt-6 rounded-[1.5rem] border bg-card p-6"><p className="text-sm text-muted-foreground">Loading roadmap readiness…</p></section>;
  const updateGate = (key: RoadmapGateKey, value: RoadmapStatus) => setDraft({ ...current, gates: { ...current.gates, [key]: value } });
  const saveAll = async () => {
    const values: Array<[string, string]> = Object.entries(current.gates).map(([key, value]) => [`roadmap_${key === "residentValidation" ? "resident_validation" : key === "supplierSetup" ? "supplier_setup" : key === "complianceReview" ? "compliance_review" : key === "qaStatus" ? "qa_status" : key === "pilotStatus" ? "pilot_status" : "expansion_status"}`, value as string]);
    values.push(["roadmap_pilot_apartments", current.settings.pilotApartments], ["roadmap_notes", current.settings.notes]);
    for (const [key, value] of values) await save.mutateAsync({ key: key as Parameters<typeof save.mutateAsync>[0]["key"], value });
  };
  const metrics = [["Verified residents", current.metrics.verifiedResidents], ["Active shops", current.metrics.activeShops], ["Available SKUs", current.metrics.availableProducts], ["Delivery partners", current.metrics.deliveryPartners], ["Orders", current.metrics.totalOrders], ["Open orders", current.metrics.openOrders], ["Delivered", current.metrics.deliveredOrders], ["Avg order value", `₹${current.metrics.averageOrderValue.toFixed(2)}`], ["Stock-outs", current.metrics.stockOuts], ["Open services", current.metrics.openServiceRequests]];
  return <section className="mt-6 rounded-[1.5rem] border bg-card p-6 shadow-sm"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><p className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.14em] text-primary"><Gauge className="h-4 w-4" />Flow-chart control room</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Roadmap Readiness</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">Real app metrics are calculated from stored data. Survey, supplier, permission, compliance, and pilot statuses must be confirmed by the owner; they are never marked complete automatically.</p></div><span className="rounded-full bg-amber-100 px-3 py-1.5 text-xs font-semibold text-amber-800">External gates require evidence</span></div><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">{metrics.map(([label, value]) => <div key={String(label)} className="rounded-xl bg-muted/60 p-3"><p className="text-lg font-semibold">{value}</p><p className="mt-1 text-[10px] font-bold uppercase tracking-wide text-muted-foreground">{label}</p></div>)}</div><div className="mt-6 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><div><div className="flex items-center gap-2"><ClipboardCheck className="h-4 w-4 text-primary" /><h3 className="font-semibold">Launch gates</h3></div><div className="mt-3 grid gap-2">{(Object.keys(roadmapGateLabels) as RoadmapGateKey[]).map(key => <label key={key} className="flex flex-col gap-2 rounded-xl border bg-background p-3 text-sm sm:flex-row sm:items-center sm:justify-between"><span>{roadmapGateLabels[key]}</span><select value={current.gates[key]} onChange={event => updateGate(key, event.target.value as RoadmapStatus)} className="rounded-lg border bg-card px-2.5 py-1.5 text-sm sm:min-w-32"><option value="pending">{roadmapStatusLabels.pending}</option><option value="in_progress">{roadmapStatusLabels.in_progress}</option><option value="complete">{roadmapStatusLabels.complete}</option><option value="blocked">{roadmapStatusLabels.blocked}</option></select></label>)}</div></div><div><div className="flex items-center gap-2"><ClipboardList className="h-4 w-4 text-primary" /><h3 className="font-semibold">Pilot controls</h3></div><label className="mt-3 block rounded-xl border bg-background p-3 text-sm"><span className="text-xs font-bold uppercase tracking-wide text-muted-foreground">Pilot apartments</span><input type="number" min="1" max="1000" value={current.settings.pilotApartments} onChange={event => setDraft({ ...current, settings: { ...current.settings, pilotApartments: event.target.value } })} className="mt-2 w-full rounded-lg border bg-card px-3 py-2" /></label><label className="mt-3 block rounded-xl border bg-background p-3 text-sm"><span className="text-xs font-bold uppercase tracking-wide text-muted-foreground">Owner notes / evidence reference</span><textarea value={current.settings.notes} onChange={event => setDraft({ ...current, settings: { ...current.settings, notes: event.target.value } })} className="mt-2 min-h-24 w-full rounded-lg border bg-card px-3 py-2" placeholder="Add survey link, permission reference, QA date, or pilot notes." /></label><Button type="button" className="mt-3 rounded-full" disabled={save.isPending} onClick={saveAll}>{save.isPending ? "Saving…" : "Save roadmap status"}</Button></div></div></section>;
}

function AdminSnapshot({ dashboard, people, announcement, setAnnouncement, onSend, sending }: { dashboard?: { orders: number; customers: number; pendingResidents: number; activeProducts: number }; people: number; announcement: string; setAnnouncement: (value: string) => void; onSend: () => void; sending: boolean }) { return <section className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><div className="rounded-[1.5rem] bg-[#315d47] p-6 text-primary-foreground"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary-foreground/65">Community intelligence</p><h2 className="mt-1 font-editorial text-3xl font-semibold">Operating snapshot</h2></div><Leaf className="h-6 w-6 text-[#e7c06a]" /></div><div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Orders", dashboard?.orders || 0], ["Residents", dashboard?.customers || 0], ["To verify", dashboard?.pendingResidents || 0], ["Live SKUs", dashboard?.activeProducts || 0]].map(([label, value]) => <div key={String(label)} className="rounded-xl bg-white/10 p-3"><p className="font-editorial text-2xl">{value}</p><p className="mt-1 text-[10px] uppercase tracking-wide text-primary-foreground/65">{label}</p></div>)}</div><p className="mt-5 text-xs text-primary-foreground/70">People managed: {people} · Payments reporting is protected on the server.</p></div><div className="rounded-[1.5rem] border bg-card p-6"><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Broadcast a neighbour note</p><textarea value={announcement} onChange={event => setAnnouncement(event.target.value)} className="mt-3 min-h-24 w-full rounded-xl border bg-background p-3 text-sm outline-none focus:ring-2 focus:ring-primary/30" placeholder="Share a delivery window, store update, or building notice." /><Button className="mt-3 rounded-full" disabled={sending || announcement.trim().length < 2} onClick={onSend}><Send className="mr-2 h-4 w-4" />{sending ? "Sending…" : "Send to all roles"}</Button></div></section>; }

function AdminControlPanel() {
  const utils = trpc.useUtils();
  const applications = trpc.admin.users.residentApplications.useQuery(); const people = trpc.admin.users.list.useQuery(); const orders = trpc.admin.operations.orders.useQuery(undefined, { refetchInterval: STAFF_ORDERS_REFRESH_MS }); const deliveryPeople = trpc.admin.operations.deliveryCandidates.useQuery(); const categories = trpc.admin.catalog.categories.useQuery(); const banners = trpc.admin.brand.banners.useQuery(); const settings = trpc.admin.brand.settings.useQuery();
  const verify = trpc.admin.users.verifyResident.useMutation({ onSuccess: () => utils.admin.users.residentApplications.invalidate() }); const role = trpc.admin.users.updateRole.useMutation({ onSuccess: () => utils.admin.users.list.invalidate() }); const assign = trpc.admin.operations.assignDelivery.useMutation({ onSuccess: () => utils.admin.operations.orders.invalidate() }); const saveCategory = trpc.admin.catalog.saveCategory.useMutation({ onSuccess: () => utils.admin.catalog.categories.invalidate() });   const saveBanner = trpc.admin.brand.saveBanner.useMutation({ onSuccess: () => utils.admin.brand.banners.invalidate() }); const saveSetting = trpc.admin.brand.saveSetting.useMutation({ onSuccess: () => utils.admin.brand.settings.invalidate() });
  const saveSplashDuration = trpc.admin.brand.setSplashDuration.useMutation({ onSuccess: result => { setSplashDurationMs(String(result.durationMs)); void utils.admin.brand.settings.invalidate(); toast.success(`Splash duration saved: ${formatSplashDurationLabel(result.durationMs)}.`); }, onError: error => toast.error(error.message) });
  const [categoryName, setCategoryName] = useState(""); const [bannerTitle, setBannerTitle] = useState(""); const [settingKey, setSettingKey] = useState(""); const [settingValue, setSettingValue] = useState(""); const [splashDurationMs, setSplashDurationMs] = useState(String(DEFAULT_SPLASH_DURATION_MS));
  const appRows = (applications.data || []) as Array<{ profile: { userId: number; apartmentUnit: string; verificationStatus: string }; name: string | null; role: string }>; const peopleRows = (people.data || []) as Array<{ id: number; name: string | null; role: "customer" | "shop_owner" | "delivery_boy" | "admin" }>; const orderRows = (orders.data || []) as Array<{ id: number; orderNumber: string; deliveryUserId: number | null }>; const deliveryRows = (deliveryPeople.data || []) as Array<{ id: number; name: string | null }>;
  useEffect(() => {
    const stored = settings.data?.find(setting => setting.settingKey === SPLASH_DURATION_SETTING_KEY);
    if (stored) setSplashDurationMs(String(parseSplashDuration(stored.settingValue)));
  }, [settings.data]);
  return <section className="mt-6 grid gap-6 xl:grid-cols-2"><div className="rounded-[1.5rem] border bg-card p-6"><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Resident governance</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Approvals and access</h2><div className="mt-4 space-y-3">{appRows.filter(row => row.profile.verificationStatus === "pending").map(row => <div key={row.profile.userId} className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-muted/65 p-3"><p className="text-sm font-semibold">{row.name || "Resident"} <span className="font-normal text-muted-foreground">· Unit {row.profile.apartmentUnit}</span></p><div className="flex gap-2"><Button size="sm" className="rounded-full" onClick={() => verify.mutate({ userId: row.profile.userId, status: "verified" })}>Approve</Button><Button size="sm" variant="outline" className="rounded-full" onClick={() => verify.mutate({ userId: row.profile.userId, status: "rejected" })}>Decline</Button></div></div>)}{!appRows.some(row => row.profile.verificationStatus === "pending") && <p className="rounded-xl border border-dashed p-4 text-sm text-muted-foreground">No resident applications are awaiting review.</p>}</div><div className="mt-5 space-y-2">{peopleRows.slice(0, 6).map(person => <label key={person.id} className="flex items-center justify-between gap-3 rounded-xl border p-3 text-sm"><span>{person.name || `User ${person.id}`}</span><select value={person.role} onChange={event => role.mutate({ userId: person.id, role: event.target.value as "customer" | "shop_owner" | "delivery_boy" | "admin" })} className="rounded-lg border bg-background px-2 py-1 text-xs"><option value="customer">Customer</option><option value="shop_owner">Shop owner</option><option value="delivery_boy">Delivery partner</option><option value="admin">Admin</option></select></label>)}</div></div><div className="rounded-[1.5rem] border bg-card p-6"><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Dispatch desk</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Delivery assignments</h2><div className="mt-4 space-y-3">{orderRows.slice(0, 6).map(order => <label key={order.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-muted/65 p-3 text-sm"><span className="font-semibold">{order.orderNumber}</span><select value={order.deliveryUserId || ""} onChange={event => event.target.value && assign.mutate({ orderId: order.id, deliveryUserId: Number(event.target.value) })} className="rounded-lg border bg-card px-2 py-1 text-xs"><option value="">Assign delivery partner</option>{deliveryRows.map(person => <option key={person.id} value={person.id}>{person.name || `Partner ${person.id}`}</option>)}</select></label>)}{!orderRows.length && <p className="rounded-xl border border-dashed p-4 text-sm text-muted-foreground">No orders are awaiting delivery assignment.</p>}</div></div><div className="rounded-[1.5rem] border bg-card p-6"><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Catalog taxonomy</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Categories</h2><form className="mt-4 flex gap-2" onSubmit={event => { event.preventDefault(); if (!categoryName.trim()) return; saveCategory.mutate({ name: categoryName.trim(), slug: categoryName.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""), isActive: true }); setCategoryName(""); }}><input value={categoryName} onChange={event => setCategoryName(event.target.value)} placeholder="New category" className="min-w-0 flex-1 rounded-xl border bg-background px-3 py-2 text-sm" /><Button type="submit" size="sm" className="rounded-full">Add</Button></form><div className="mt-4 flex flex-wrap gap-2">{(categories.data || []).map(category => <span key={category.id} className="rounded-full bg-primary/10 px-3 py-1 text-xs font-semibold text-primary">{category.name}</span>)}</div></div><div className="rounded-[1.5rem] border bg-card p-6"><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Brand and settings</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Homepage controls</h2><form className="mt-4 grid gap-2" onSubmit={event => { event.preventDefault(); if (!bannerTitle.trim()) return; saveBanner.mutate({ title: bannerTitle.trim(), isActive: true, displayOrder: (banners.data || []).length }); setBannerTitle(""); }}><input value={bannerTitle} onChange={event => setBannerTitle(event.target.value)} placeholder="Banner title" className="rounded-xl border bg-background px-3 py-2 text-sm" /><Button type="submit" size="sm" className="w-fit rounded-full">Add banner</Button></form><form className="mt-4 rounded-2xl border border-primary/15 bg-primary/5 p-4" onSubmit={event => { event.preventDefault(); const durationMs = Number(splashDurationMs); if (!Number.isInteger(durationMs) || durationMs < MIN_SPLASH_DURATION_MS || durationMs > MAX_SPLASH_DURATION_MS) { toast.error(`Choose a duration from ${MIN_SPLASH_DURATION_MS} to ${MAX_SPLASH_DURATION_MS} milliseconds.`); return; } saveSplashDuration.mutate({ durationMs }); }}><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm font-semibold">Customer splash screen</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Choose how long the HariCart launch screen stays visible. Applies on the next customer launch.</p></div><span className="rounded-full bg-white px-3 py-1 text-xs font-semibold text-primary">{formatSplashDurationLabel(Number(splashDurationMs))}</span></div><div className="mt-3 flex flex-wrap items-end gap-2"><label className="text-xs font-semibold text-muted-foreground">Duration in milliseconds<input aria-label="Customer splash duration in milliseconds" type="number" min={MIN_SPLASH_DURATION_MS} max={MAX_SPLASH_DURATION_MS} step="100" value={splashDurationMs} onChange={event => setSplashDurationMs(event.target.value)} className="mt-1 h-10 w-40 rounded-xl border bg-background px-3 text-sm text-foreground" /></label><Button type="submit" size="sm" className="rounded-full" disabled={saveSplashDuration.isPending}>{saveSplashDuration.isPending ? "Saving…" : "Save splash duration"}</Button></div></form><form className="mt-4 grid gap-2" onSubmit={event => { event.preventDefault(); if (!settingKey.trim()) return; saveSetting.mutate({ key: settingKey.trim(), value: settingValue }); setSettingKey(""); setSettingValue(""); }}><input value={settingKey} onChange={event => setSettingKey(event.target.value)} placeholder="Setting key" className="rounded-xl border bg-background px-3 py-2 text-sm" /><input value={settingValue} onChange={event => setSettingValue(event.target.value)} placeholder="Setting value" className="rounded-xl border bg-background px-3 py-2 text-sm" /><Button type="submit" size="sm" variant="outline" className="w-fit rounded-full">Save setting</Button></form><p className="mt-4 text-xs text-muted-foreground">{(banners.data || []).length} banner(s) · {(settings.data || []).length} saved setting(s)</p></div></section>;
}

function AdminCommercePanel() {
  const utils = trpc.useUtils();
  const market = trpc.admin.operations.market.useQuery();
  const shops = trpc.admin.operations.shops.useQuery();
  const payments = trpc.admin.operations.payments.useQuery();
  const setMarket = trpc.admin.operations.setMarket.useMutation({ onSuccess: result => { market.refetch(); toast.success(result.isOpen ? "Market is now open" : "Market is now closed"); }, onError: error => toast.error(error.message) });
  const saveShop = trpc.admin.operations.saveShop.useMutation({ onSuccess: () => { shops.refetch(); toast.success("Shop saved"); }, onError: error => toast.error(error.message) });
  const deleteShop = trpc.admin.operations.deleteShop.useMutation({ onSuccess: () => { shops.refetch(); toast.success("Shop deleted"); }, onError: error => toast.error(error.message) });
  const updatePayment = trpc.admin.operations.updatePayment.useMutation({ onSuccess: () => { payments.refetch(); utils.admin.operations.orders.invalidate(); toast.success("Payment record updated"); }, onError: error => toast.error(error.message) });
  const [shopName, setShopName] = useState("");
  const [shopRate, setShopRate] = useState("12.50");
  const isOpen = market.data?.isOpen ?? true;
  return <section className="mt-6 grid gap-6 xl:grid-cols-3">
    <div className="rounded-[1.5rem] border bg-card p-6">
      <div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Store availability</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Market {isOpen ? "ON" : "OFF"}</h2></div><span className={`grid h-11 w-11 place-items-center rounded-full ${isOpen ? "bg-primary/10 text-primary" : "bg-amber-100 text-amber-700"}`}><Power className="h-5 w-5" /></span></div>
      <p className="mt-3 text-sm leading-6 text-muted-foreground">Turn new ordering on or off for every resident. Existing orders and operational records stay unchanged.</p>
      <Button className="mt-5 w-full rounded-full" variant={isOpen ? "outline" : "default"} disabled={setMarket.isPending} onClick={() => setMarket.mutate({ isOpen: !isOpen })}>{setMarket.isPending ? "Updating…" : isOpen ? "Turn market off" : "Turn market on"}</Button>
    </div>
    <div className="rounded-[1.5rem] border bg-card p-6">
      <div className="flex items-center gap-2"><span className="grid h-9 w-9 place-items-center rounded-full bg-primary/10 text-primary"><Store className="h-4 w-4" /></span><div><p className="text-xs font-bold uppercase tracking-[.14em] text-primary">Shop management</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Shops</h2></div></div>
      <form className="mt-4 flex gap-2" onSubmit={event => { event.preventDefault(); if (!shopName.trim()) return; saveShop.mutate({ name: shopName.trim(), commissionRate: shopRate, status: "active" }); setShopName(""); }}><input required value={shopName} onChange={event => setShopName(event.target.value)} placeholder="Shop name" className="min-w-0 flex-1 rounded-xl border bg-background px-3 py-2 text-sm" /><input required value={shopRate} onChange={event => setShopRate(event.target.value)} aria-label="Commission rate" className="w-20 rounded-xl border bg-background px-2 py-2 text-sm" /><Button type="submit" size="sm" className="rounded-full" disabled={saveShop.isPending}>Add</Button></form>
      <div className="mt-4 space-y-2">{(shops.data || []).map(shop => <div key={shop.id} className="flex items-center justify-between gap-3 rounded-xl bg-muted/65 p-3"><div className="min-w-0"><p className="truncate text-sm font-semibold">{shop.name}</p><p className="text-xs text-muted-foreground">{shop.status} · {shop.commissionRate}% commission</p></div><Button size="icon" variant="outline" className="shrink-0 rounded-full" aria-label={`Delete ${shop.name}`} disabled={deleteShop.isPending} onClick={() => deleteShop.mutate({ id: shop.id })}><Trash2 className="h-4 w-4" /></Button></div>)}{!shops.data?.length && <p className="rounded-xl border border-dashed p-4 text-sm text-muted-foreground">No shops have been added yet.</p>}</div>
    </div>
    <div className="rounded-[1.5rem] border bg-card p-6">
      <div className="flex items-center gap-2"><span className="grid h-9 w-9 place-items-center rounded-full bg-primary/10 text-primary"><CreditCard className="h-4 w-4" /></span><div><p className="text-xs font-bold uppercase tracking-[.14em] text-primary">Payment desk</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Review payments</h2></div></div>
      <div className="mt-4 space-y-2">{(payments.data || []).slice(0, 8).map(payment => <div key={payment.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-muted/65 p-3"><div><p className="text-sm font-semibold">Order #{payment.orderId} · ₹{payment.amount}</p><p className="text-xs text-muted-foreground">{payment.providerReference || "No provider reference"}</p></div><select value={payment.status} onChange={event => updatePayment.mutate({ id: payment.id, status: event.target.value as "pending" | "paid" | "failed" | "refunded", providerReference: payment.providerReference || undefined })} className="rounded-lg border bg-card px-2 py-1 text-xs"><option value="pending">Pending</option><option value="paid">Paid</option><option value="failed">Failed</option><option value="refunded">Refunded</option></select></div>)}{!payments.data?.length && <p className="rounded-xl border border-dashed p-4 text-sm text-muted-foreground">No payment records are available yet.</p>}</div>
    </div>
  </section>;
}

function AdminInvitePanel() {
  const invites = trpc.admin.invites.list.useQuery();
  const addInvite = trpc.admin.invites.add.useMutation({ onSuccess: () => { invites.refetch(); setPhone(""); setName(""); setUnit(""); toast.success("Member added to the invite list"); }, onError: error => toast.error(error.message) });
  const revokeInvite = trpc.admin.invites.revoke.useMutation({ onSuccess: () => { invites.refetch(); toast.success("Invite access revoked"); }, onError: error => toast.error(error.message) });
  const [phone, setPhone] = useState("");
  const [name, setName] = useState("");
  const [unit, setUnit] = useState("");
  const submit = (event: FormEvent) => { event.preventDefault(); if (!phone.trim() || !unit.trim()) return; addInvite.mutate({ phone: phone.trim(), name: name.trim() || undefined, apartmentUnit: unit.trim() }); };
  return <section className="mt-6 rounded-[1.5rem] border bg-card p-6">
    <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div className="flex items-center gap-2"><span className="grid h-9 w-9 place-items-center rounded-full bg-primary/10 text-primary"><UserPlus className="h-4 w-4" /></span><div><p className="text-xs font-bold uppercase tracking-[.14em] text-primary">Access governance</p><h2 className="mt-1 font-editorial text-2xl font-semibold">Invite list</h2></div></div><p className="max-w-md text-sm leading-6 text-muted-foreground">Only phone numbers on this list can complete resident verification and place orders once invite-only access is active.</p></div>
    <form onSubmit={submit} className="mt-5 grid gap-3 md:grid-cols-[1fr_1fr_150px_auto]"><input required value={phone} onChange={event => setPhone(event.target.value)} placeholder="Mobile number" inputMode="tel" className="rounded-xl border bg-background px-3 py-2 text-sm" /><input value={name} onChange={event => setName(event.target.value)} placeholder="Resident name (optional)" className="rounded-xl border bg-background px-3 py-2 text-sm" /><input required value={unit} onChange={event => setUnit(event.target.value)} placeholder="Flat / unit" className="rounded-xl border bg-background px-3 py-2 text-sm" /><Button type="submit" className="rounded-full" disabled={addInvite.isPending}><UserPlus className="mr-2 h-4 w-4" />{addInvite.isPending ? "Adding…" : "Add member"}</Button></form>
    <div className="mt-5 grid gap-2 md:grid-cols-2">{(invites.data || []).map(invite => <div key={invite.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-muted/65 p-3"><div className="min-w-0"><p className="truncate text-sm font-semibold">{invite.name || "Invited resident"} <span className="font-normal text-muted-foreground">· {invite.phone}</span></p><p className="mt-1 text-xs text-muted-foreground">Unit {invite.apartmentUnit} · <span className={invite.status === "revoked" ? "text-red-700" : invite.status === "joined" ? "text-primary" : "text-amber-700"}>{invite.status}</span></p></div>{invite.status !== "revoked" && <Button size="sm" variant="outline" className="rounded-full" disabled={revokeInvite.isPending} onClick={() => revokeInvite.mutate({ id: invite.id })}><UserX className="mr-1.5 h-3.5 w-3.5" />Revoke</Button>}</div>)}{!invites.data?.length && <p className="rounded-xl border border-dashed p-4 text-sm text-muted-foreground md:col-span-2">No invited members yet. Add the first phone number above.</p>}</div>
  </section>;
}

